'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ROLES=['Администратор','Оператор УОСО','Оператор УОСО-2','Оператор ФД','Исполнитель ФД','Исполнитель УОСО'];
const FIELDS=['Дата','Наименование заявки','ИД заявки','Дата регистрации заявки','Время выгрузки','ИД гражданина','Округ','Район','Дата до которой необходимо согласовать ФД','Исполнитель ФД','Дата План ФД','Дата Факт ФД','Статус ФД','Номер анкеты','Дата возврата к заявке','Исполнитель УОСО','Дата направления в КЦ','Дата возврата из КЦ','Дата направления Запроса к НП','Дата Возврата от НП','Расчётная дата решения','Дата решения','Статус заявки'];
const STATUSES=['Проведена','Отказ от ФД','Недозвон','Госпитализация','Помещен в стационарное учреждение ГЦ/СД'];
const STAGES=[['fd_wait','Ожидают назначения ФД','▤'],['fd_work','В работе ФД','◷'],['uoso_wait','Ожидают назначения УОСО','☷'],['uoso_work','В работе УОСО','✓'],['done','Завершены','□']];
const EDIT={0:[0,1,3,4,5,6,7,10,11,12,13,14,16,17,18,19,21],4:[10,11,12,13,14],5:[14,16,17,18,19,21]};
let user=null,csrf='',users=[],holidays=[],view='dashboard',page=1,selected=new Set(),rows=[],names={},generation=0,notificationCount=0,filter={query:'',citizen:'',from:'',to:'',stage:'',tab:'',sort:'3',desc:'1'},notificationType='';
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',6500);}
async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(data!==undefined?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{})},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok){if(response.status===401&&path!='/auth/login'){user=null;login();}const e=new Error(result.error||'Ошибка запроса');Object.assign(e,result,{status:response.status});throw e;}return result;}
function run(fn){return async e=>{e?.preventDefault();try{await fn(e);}catch(error){toast(error.message);}};}
async function busy(button,fn){button.disabled=true;try{return await fn();}finally{if(button.isConnected)button.disabled=false;}}
function fmt(value,time=false){if(!value)return '—';const s=String(value),m=s.match(/^(\d{4})-(\d{2})-(\d{2})(?:T| )?(.*)$/);return m?`${m[3]}.${m[2]}.${m[1]}`+(time&&m[4]?' '+m[4].slice(0,8):''):s;}
function valueOf(row,i){const v=row.data[i];return i===9||i===15?(names[v]||users.find(u=>u.id===v)?.name||'—'):([8,10,11,16,17,18,19,20,21].includes(i)?fmt(v):i===14?fmt(v,true):v||'—');}
function modal(title,body,footer='',small=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button id="closeModal" aria-label="Закрыть">×</button></div>${body}<div id="modalError" role="alert"></div><div class="modal-footer">${footer}</div></section></div>`;$('#closeModal').onclick=closeModal;$('#overlay input, #overlay select')?.focus();}
function closeModal(){$('#overlay').innerHTML='';}
function modalError(error){const box=$('#modalError');if(box)box.innerHTML=`<div class="error">${esc(error.message)}</div>`;else toast(error.message);}
function login(){generation++;closeModal();$('#app').innerHTML=`<div class="login"><section class="login-intro"><div class="brand">СКЗ<small>Контроль обработки заявок</small></div><h1>От поступления заявки<br>до принятия решения</h1><p>Регистрация → ФД → УОСО → Решение</p></section><section class="login-form"><form id="loginForm"><h1>Вход в систему</h1><p class="muted">Введите логин и пароль своей учётной записи</p><label>Логин<input id="username" autocomplete="username" required></label><label>Пароль<input id="password" type="password" autocomplete="current-password" required></label><div id="loginError" role="alert"></div><button class="primary" id="loginButton">Войти</button><p class="muted">Восстановление пароля — через Администратора</p></form></section></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();await busy($('#loginButton'),async()=>{try{const r=await api('/auth/login','POST',{login:$('#username').value,password:$('#password').value});csrf=r.csrf;user=r.user;$('#password').value='';await start();}catch(error){$('#loginError').innerHTML=`<div class="error">${esc(error.message)}</div>`;}});};}
async function start(){if(user.mustChange){changePassword(true);return;}const data=await api('/state');user=data.user;users=data.users;holidays=data.holidays;view='dashboard';page=1;selected.clear();shell();await render();}
function changePassword(required=false){if(required)$('#app').innerHTML='<main><h1>Первый вход</h1><p>Установите новый пароль для продолжения работы.</p></main>';modal('Смена пароля',`<label class="field">Текущий пароль<input type="password" id="oldPassword" autocomplete="current-password"></label><label class="field">Новый пароль<input type="password" id="newPassword" autocomplete="new-password"></label><label class="field">Повторите новый пароль<input type="password" id="repeatPassword" autocomplete="new-password"></label><p class="muted">Минимум 8 символов.</p>`,'<button class="primary" id="changePassword">Сохранить пароль</button>',true);if(required)$('#closeModal').onclick=run(logout);$('#changePassword').onclick=()=>busy($('#changePassword'),async()=>{try{if($('#newPassword').value!==$('#repeatPassword').value)throw new Error('Пароли не совпадают');const r=await api('/auth/change-password','POST',{current:$('#oldPassword').value,password:$('#newPassword').value});csrf=r.csrf;user.mustChange=false;closeModal();await start();toast('Пароль изменён');}catch(e){modalError(e);}});}
async function logout(){await api('/auth/logout','POST',{});user=null;csrf='';users=[];rows=[];selected.clear();login();}
function menu(){const m=[['dashboard','Дашборд'],['requests',user.role>=4?'Назначенные заявки':user.role===1?'Загруженные заявки':'Заявки']];if([0,1].includes(user.role))m.push(['upload','Загрузка Excel']);if(user.role===0)m.push(['users','Пользователи'],['holidays','Праздничные дни'],['executors','Исполнители'],['archive','Архив заявок'],['audit','Журнал действий'],['template','Настройки шаблона']);if(user.role!==1)m.push(['notifications','Уведомления']);if([0,2,3].includes(user.role))m.push(['export','Выгрузка']);return m;}
function shell(){const title=menu().find(m=>m[0]===view)?.[1]||'СКЗ';$('#app').innerHTML=`<div class="shell"><aside><div class="brand">▣ СКЗ<small>Контроль обработки заявок</small></div><nav>${menu().map(([key,label])=>`<button data-nav="${key}" class="${view===key?'active':''}">${label}${key==='notifications'?` <span class="count" id="notificationCount">${notificationCount}</span>`:''}</button>`).join('')}</nav><div class="identity"><strong>${esc(user.name)}</strong><small>${ROLES[user.role]}</small><button id="passwordSettings">Сменить пароль</button><button id="logout">Выйти</button></div></aside><main><header><div><h1>${title}</h1><span class="muted">Система контроля обработки заявок</span></div></header><div id="content"></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=run(()=>navigate(b.dataset.nav)));$('#logout').onclick=run(logout);$('#passwordSettings').onclick=()=>changePassword();}
async function navigate(next){view=next;page=1;selected.clear();filter.stage='';shell();await render();}
async function render(){const token=++generation;try{const fn={dashboard:dashboard,requests:list,archive:list,users:userList,executors:userList,upload:upload,holidays:calendar,template:templateView,audit:auditView,notifications:notificationsView,export:exportView}[view];await fn(token);}catch(e){if(token===generation&&$('#content'))$('#content').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
function requestLinks(){document.querySelectorAll('[data-request]').forEach(b=>b.onclick=run(()=>detail(b.dataset.request)));}
function recentTable(items){return items.length?`<div class="table-scroll"><table><thead><tr><th>ИД заявки</th><th>Наименование заявки</th><th>Дата регистрации</th></tr></thead><tbody>${items.map(r=>`<tr><td><button class="link" data-request="${esc(r.data[2])}">${esc(r.data[2])}</button></td><td class="wrap">${esc(r.data[1])}</td><td>${esc(r.data[3])}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Заявки не найдены</div>';}
async function dashboard(token){const d=await api('/dashboard');if(token!==generation)return;$('#content').innerHTML=`${user.role!==1?`<div class="cards">${STAGES.map(([key,label,symbol])=>`<button class="card" data-stage="${key}"><span class="symbol">${symbol}</span><b>${d.counts[key]||0}</b><span>${label}</span></button>`).join('')}</div><p class="legend">Этапы учитывают доступные вам активные заявки. Каждая заявка относится к одному этапу.</p>`:''}<div class="dashboard-grid"><section class="panel"><h2>Последние заявки</h2>${recentTable(d.rows)}</section><section class="panel"><h2>Быстрые действия</h2><div class="quick"><button data-go="requests">Открыть заявки →</button>${[0,1].includes(user.role)?'<button data-go="upload">Загрузить Excel →</button>':''}${user.role===0?'<button data-go="users">Пользователи →</button>':''}${user.role!==1?'<button data-go="notifications">Уведомления →</button>':''}</div></section></div>`;document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=run(async()=>{view='requests';filter.stage=b.dataset.stage;page=1;shell();await render();}));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=run(()=>navigate(b.dataset.go)));requestLinks();}
function filterHtml(){return `<div class="toolbar"><input id="query" placeholder="ИД заявки" value="${esc(filter.query)}"><input id="citizen" placeholder="ИД гражданина" value="${esc(filter.citizen)}"><label>С <input id="from" type="date" value="${esc(filter.from)}"></label><label>По <input id="to" type="date" value="${esc(filter.to)}"></label>${user.role!==1?`<select id="stage"><option value="">Все этапы</option>${STAGES.map(([k,l])=>`<option value="${k}" ${filter.stage===k?'selected':''}>${l}</option>`).join('')}</select>`:''}</div><div class="toolbar"><label>Сортировка <select id="sort">${[2,3,...(user.role===1?[]:[12,22])].map(i=>`<option value="${i}" ${filter.sort===String(i)?'selected':''}>${FIELDS[i]}</option>`).join('')}</select></label><select id="desc"><option value="1" ${filter.desc==='1'?'selected':''}>По убыванию</option><option value="0" ${filter.desc==='0'?'selected':''}>По возрастанию</option></select></div>`;}
async function list(token){$('#content').innerHTML=`<section class="panel">${filterHtml()}<div class="toolbar" id="assignButtons">${view!=='archive'&&[0,3].includes(user.role)?'<button id="assignFD">Назначить Исполнителя ФД</button>':''}${view!=='archive'&&[0,2].includes(user.role)?'<button id="assignUOSO">Назначить Исполнителя УОСО</button>':''}</div><div id="requestTable">Загрузка…</div></section>`;for(const key of ['query','citizen','from','to','stage','sort','desc']){const input=$('#'+key);if(input)input.oninput=()=>{filter[key]=input.value;page=1;selected.clear();clearTimeout(list.timer);list.timer=setTimeout(()=>loadTable(token).catch(e=>toast(e.message)),250);};}if($('#assignFD'))$('#assignFD').onclick=()=>assign(9);if($('#assignUOSO'))$('#assignUOSO').onclick=()=>assign(15);await loadTable(token);}
async function loadTable(token=generation){const seq=++loadTable.sequence;const d=await api('/requests?'+new URLSearchParams({...filter,page,archive:view==='archive'?'1':'0'}));if(token!==generation||seq!==loadTable.sequence||!$('#requestTable'))return;rows=d.rows;Object.assign(names,d.names);const indices=[2,5,1,3,...FIELDS.map((_,i)=>i).filter(i=>![2,5,1,3].includes(i)&& (user.role!==1||i<8))],check=view!=='archive'&&[0,2,3].includes(user.role);const widths=[150,150,260,190];const sticky=(j)=>j<4?`class="sticky" style="left:${(check?48:0)+widths.slice(0,j).reduce((a,b)=>a+b,0)}px;min-width:${widths[j]}px;max-width:${widths[j]}px;overflow:hidden;text-overflow:ellipsis"`:'';$('#requestTable').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr>${check?'<th class="sticky" style="left:0;min-width:48px"><input type="checkbox" id="selectAll" aria-label="Выбрать страницу"></th>':''}${indices.map((i,j)=>`<th ${sticky(j)}>${FIELDS[i]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.isNew?'fresh':''}">${check?`<td class="sticky" style="left:0"><input type="checkbox" data-select="${esc(r.data[2])}" ${selected.has(r.data[2])?'checked':''} aria-label="Выбрать заявку ${esc(r.data[2])}"></td>`:''}${indices.map((i,j)=>`<td ${sticky(j)} title="${esc(valueOf(r,i))}">${i===2?`<button class="link" data-request="${esc(r.data[2])}">${esc(r.data[2])}</button>${r.isNew?' <span class="tag">Новая</span>':''}`:esc(valueOf(r,i))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${pager(d.hasNext)}`:`<div class="empty">Заявки не найдены</div>${page>1?pager(false):''}`;requestLinks();bindPager(()=>loadTable());document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select));if($('#selectAll'))$('#selectAll').onchange=e=>{document.querySelectorAll('[data-select]').forEach(c=>{c.checked=e.target.checked;c.onchange();});};}
loadTable.sequence=0;
function pager(next){return `<div class="pager"><button id="previous" ${page===1?'disabled':''}>← Назад</button><span>Страница ${page}</span><button id="next" ${next?'':'disabled'}>Далее →</button></div>`;}
function bindPager(fn){if($('#previous'))$('#previous').onclick=run(async()=>{page--;selected.clear();await fn();});if($('#next'))$('#next').onclick=run(async()=>{page++;selected.clear();await fn();});}
async function detail(id){const d=await api('/requests/'+encodeURIComponent(id)),r=d.row;Object.assign(names,d.names);const editable=r.archived?[]:(EDIT[user.role]||[]);const inputs=FIELDS.map((label,i)=>{if(user.role===1&&i>=8)return '';const v=r.data[i];let control=`<div class="readonly">${esc(valueOf(r,i))}</div>`;if(editable.includes(i)){if(i===12)control=`<select data-field="12"><option value="">Выберите статус</option>${STATUSES.map(s=>`<option ${s===v?'selected':''}>${s}</option>`).join('')}</select>`;else control=`<input data-field="${i}" type="${i===14?'datetime-local':[10,11,16,17,18,19,21].includes(i)?'date':'text'}" ${i===14?'step="1"':''} value="${esc(v)}">`;}return `<div class="field"><label>${label}</label>${control}</div>`;}).join('');modal('Заявка '+id,`${r.archived?'<div class="note">Архивная заявка. Редактирование недоступно.</div>':''}<div class="fields">${inputs}</div>`,editable.length?'<button id="cancelDetail">Отмена</button><button class="primary" id="saveDetail">Сохранить</button>':'');if($('#cancelDetail'))$('#cancelDetail').onclick=closeModal;await api('/requests/'+encodeURIComponent(id)+'/read','POST',{});if($('#saveDetail'))$('#saveDetail').onclick=()=>busy($('#saveDetail'),async()=>{try{const changes={};document.querySelectorAll('[data-field]').forEach(input=>{const i=Number(input.dataset.field);if(input.value!==String(r.data[i]??''))changes[i]=input.value;});const send=confirm=>api('/requests/'+encodeURIComponent(id),'PATCH',{revision:r.revision,changes,confirm});try{await send(false);}catch(e){if(!e.confirmationRequired)throw e;if(!window.confirm('Сохранить изменения по заявке? После завершения заявка будет недоступна исполнителю для редактирования.'))return;await send(true);}closeModal();await render();toast(Object.keys(changes).length?'Изменения сохранены':'Нет изменений');}catch(e){modalError(e);}});}
function assign(field){if(!selected.size){toast('Выберите заявки галочками');return;}const active=users.filter(u=>u.active&&u.role===(field===9?4:5));modal('Назначить Исполнителя '+(field===9?'ФД':'УОСО'),`<p>Выбрано заявок: ${selected.size}</p><label class="field">Исполнитель<select id="executor"><option value="">Выберите исполнителя</option>${active.map(u=>`<option value="${u.id}">${esc(u.name)} (${esc(u.login)})</option>`).join('')}</select></label>`,'<button id="cancelAssign">Отмена</button><button class="primary" id="saveAssign">Назначить</button>',true);$('#cancelAssign').onclick=closeModal;$('#saveAssign').onclick=()=>busy($('#saveAssign'),async()=>{try{const userId=Number($('#executor').value);if(!userId)throw new Error('Выберите исполнителя');const send=replace=>api('/requests/assign','POST',{field,userId,ids:[...selected],replace});try{await send(false);}catch(e){if(!e.confirmationRequired)throw e;if(!confirm(`Уже назначен Исполнитель: ${e.assigned} заявок. Заменить?`))return;await send(true);}closeModal();selected.clear();await render();toast('Исполнитель назначен');}catch(e){modalError(e);}});}
async function userList(token){const d=await api('/state');if(token!==generation)return;users=d.users;$('#content').innerHTML='<section class="panel"><div class="toolbar"><input id="userSearch" placeholder="Поиск по ФИО"><button class="primary" id="addUser">Создать пользователя</button></div><div id="usersTable"></div></section>';const draw=()=>{const norm=s=>s.toLocaleLowerCase('ru').trim().replace(/\s+/g,' '),q=norm($('#userSearch').value),list=users.filter(u=>norm(u.name).includes(q)&&(view!=='executors'||u.role>=4));$('#usersTable').innerHTML=list.length?`<div class="table-scroll"><table><thead><tr><th>ФИО</th><th>Логин</th><th>Роль</th><th>Дата создания</th><th>Статус</th><th></th></tr></thead><tbody>${list.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.login)}</td><td>${ROLES[u.role]}</td><td>${fmt(u.created)}</td><td>${u.active?'Активен':'Заблокирован'}</td><td><button data-edit-user="${u.id}">Изменить</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Пользователи не найдены</div>';document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>editUser(users.find(u=>u.id===Number(b.dataset.editUser))));};$('#userSearch').oninput=draw;$('#addUser').onclick=()=>editUser();draw();}
function editUser(u){modal(u?'Пользователь':'Создать пользователя',`<label class="field">ФИО<input id="userName" value="${esc(u?.name||'')}"></label><label class="field">Логин<input id="userLogin" value="${esc(u?.login||'')}" autocomplete="off"></label><label class="field">Роль<select id="userRole">${ROLES.map((r,i)=>`<option value="${i}" ${(u?.role??4)===i?'selected':''}>${r}</option>`).join('')}</select></label>${u?`<label class="field">Статус<select id="userActive"><option value="1" ${u.active?'selected':''}>Активен</option><option value="0" ${u.active?'':'selected'}>Заблокирован</option></select></label><p class="muted">Создан: ${fmt(u.created)}</p><button id="resetUser">Сбросить пароль</button>`:'<label class="field">Временный пароль<input type="password" id="initialPassword" autocomplete="new-password"></label><p class="muted">Пользователь обязательно сменит пароль при первом входе.</p>'}`,'<button class="primary" id="saveUser">Сохранить</button>',true);$('#saveUser').onclick=()=>busy($('#saveUser'),async()=>{try{const d={name:$('#userName').value,login:$('#userLogin').value,role:Number($('#userRole').value),...(u?{active:$('#userActive').value==='1'}:{password:$('#initialPassword').value})};await api('/users'+(u?'/'+u.id:''),u?'PATCH':'POST',d);closeModal();await render();toast('Пользователь сохранён');}catch(e){modalError(e);}});if(u)$('#resetUser').onclick=()=>{modal('Сбросить пароль',`<p>${esc(u.name)}</p><label class="field">Новый временный пароль<input type="password" id="resetValue" autocomplete="new-password"></label><p class="muted">Все сессии пользователя будут завершены. При входе потребуется смена пароля.</p>`,'<button id="resetConfirm" class="primary">Сбросить пароль</button>',true);$('#resetConfirm').onclick=()=>busy($('#resetConfirm'),async()=>{try{await api('/users/'+u.id+'/reset-password','POST',{password:$('#resetValue').value});closeModal();if(u.id===user.id){user=null;login();}else toast('Пароль сброшен');}catch(e){modalError(e);}});};}
function readExcel(file){if(!/\.(xlsx|csv)$/i.test(file.name))throw new Error('Недопустимый формат файла. Загрузите .xlsx или .csv');return file.arrayBuffer().then(data=>{const wb=XLSX.read(data,{type:'array',cellDates:false,raw:true});if(!wb.SheetNames.length)return [];return XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:'',blankrows:true,raw:true});});}
function excelDate(value,time=false){if(typeof value!=='number')return String(value??'');const d=XLSX.SSF.parse_date_code(value);if(!d)return String(value);const pad=n=>String(n).padStart(2,'0');return `${pad(d.d)}.${pad(d.m)}.${d.y}`+(time?` ${pad(d.H)}:${pad(d.M)}:${pad(d.S)}`:'');}
async function upload(){ $('#content').innerHTML='<section class="panel"><h2>Загрузка заявок</h2><p class="muted">.xlsx или .csv, до 9999 строк. Восемь столбцов в порядке шаблона.</p><div class="toolbar"><input type="file" id="uploadFile" accept=".xlsx,.csv"><button id="downloadTemplate">Скачать шаблон</button></div><div id="preview"></div></section>';$('#downloadTemplate').onclick=run(()=>download('/templates/download','Шаблон.xlsx'));$('#uploadFile').onchange=run(async()=>{const file=$('#uploadFile').files[0];if(!file)return;$('#preview').textContent='Проверка файла…';try{const values=await readExcel(file),header=values.shift()||[],data={header,rows:values.map(r=>r.map((v,i)=>i===3?excelDate(v,true):i===0?excelDate(v):String(v??'')))};const result=await api('/imports/preview','POST',data);$('#preview').innerHTML=`<div class="note">Создано: ${result.created} / Пропущено: ${result.skipped} / Ошибки: ${result.errors}</div>${result.created===0?'<div class="note">Все строки являются дубликатами. Новые заявки не созданы.</div>':''}${recentTable(data.rows.slice(0,20).map(data=>({data})))}<p class="muted">Предпросмотр: первые 20 строк</p><div class="toolbar"><button class="primary" id="commitUpload" ${!result.created?'disabled':''}>Загрузить</button><button id="cancelUpload">Отмена</button></div>`;$('#cancelUpload').onclick=upload;$('#commitUpload').onclick=()=>busy($('#commitUpload'),async()=>{try{const r=await api('/imports/commit','POST',data);await upload();toast(`Файл загружен. Создано заявок: ${r.created}. Пропущено дубликатов: ${r.skipped}. Ошибок: ${r.errors}`);}catch(e){toast(e.message);}});}catch(e){$('#preview').innerHTML=`<div class="error">${esc(e.message)}</div><div class="toolbar"><button disabled>Загрузить</button><button id="cancelUpload">Отмена</button></div>`;$('#cancelUpload').onclick=upload;}});}
async function calendar(token){const d=await api('/state');if(token!==generation)return;holidays=d.holidays;$('#content').innerHTML=`<section class="panel"><div class="toolbar"><input type="date" id="holidayDate"><button id="addHoliday">Добавить дату</button><label>Загрузить .xlsx / .csv <input type="file" id="holidayFile" accept=".xlsx,.csv"></label><button class="danger" id="clearHolidays">Удалить все праздники</button></div><p class="muted">Одна колонка «Дата». Повторяющиеся даты пропускаются.</p><div class="table-scroll"><table><tbody>${holidays.sort().map(d=>`<tr><td>${fmt(d)}</td><td><button data-remove-holiday="${d}">Удалить</button></td></tr>`).join('')}</tbody></table></div></section>`;const save=async data=>{await api('/holidays','POST',data);await render();};$('#addHoliday').onclick=run(()=>save({dates:[$('#holidayDate').value]}));$('#clearHolidays').onclick=run(async()=>{if(confirm('Удалить все праздники?'))await save({clear:true});});document.querySelectorAll('[data-remove-holiday]').forEach(b=>b.onclick=run(()=>save({remove:b.dataset.removeHoliday})));$('#holidayFile').onchange=run(async()=>{const v=await readExcel($('#holidayFile').files[0]);if(v.shift()?.join()!=='Дата'||v.some(r=>r.length!==1||!r[0]))throw new Error('Файл должен содержать одну колонку «Дата» без пустых строк');await save({dates:v.map(r=>excelDate(r[0]))});});}
async function templateView(token){const d=await api('/templates');if(token!==generation)return;$('#content').innerHTML=`<section class="panel"><h2>Шаблон загрузки</h2><div class="toolbar"><input type="file" id="templateFile" accept=".xlsx,.csv"><button id="templateDownload">Скачать текущий шаблон</button></div><h3>История шаблонов</h3><div class="table-scroll"><table><thead><tr><th>Файл</th><th>Загрузил</th><th>Дата</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${esc(r.filename)}</td><td>${esc(r.full_name)}</td><td>${esc(r.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`;$('#templateDownload').onclick=run(()=>download('/templates/download','Шаблон.xlsx'));$('#templateFile').onchange=run(async()=>{const file=$('#templateFile').files[0];if(!file)return;const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await api('/templates','POST',{filename:file.name,content:btoa(binary)});await render();toast('Шаблон сохранён');});}
async function notificationsView(token){const d=await api('/notifications?'+new URLSearchParams({page,type:notificationType}));if(token!==generation)return;notificationCount=d.unread;$('#content').innerHTML=`<section class="panel"><div class="toolbar"><label>Статус <select id="notificationType"><option value="">Все</option><option value="new" ${notificationType==='new'?'selected':''}>Новая заявка</option><option value="return" ${notificationType==='return'?'selected':''}>Возврат к заявке</option></select></label></div>${d.rows.length?`<div class="table-scroll"><table><thead><tr><th>Статус</th><th>Заявка</th><th>Сообщение</th><th>Время возврата</th>${user.role===0?'<th>Специалист</th>':''}</tr></thead><tbody>${d.rows.map(n=>`<tr class="${!n.read_at?'fresh':''}"><td><span class="tag">${n.type==='new'?'Новая заявка':'Возврат к заявке'}</span></td><td><button class="link" data-request="${esc(n.request_id)}">${esc(n.request_id)}</button></td><td>${esc(n.message)}</td><td>${esc(fmt(n.due_date,true))}</td>${user.role===0?`<td>${esc(n.recipient)}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">Уведомлений нет</div>'}${pager(d.hasNext)}</section>`;$('#notificationType').onchange=run(async()=>{notificationType=$('#notificationType').value;page=1;await render();});requestLinks();bindPager(render);}
async function auditView(token){const d=await api('/audit?page='+page);if(token!==generation)return;$('#content').innerHTML=`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Когда / Кто</th><th>Действие</th><th>Заявка</th><th>До</th><th>После</th></tr></thead><tbody>${d.rows.map(a=>`<tr><td>${esc(a.occurred_at)}<br>${esc(a.full_name)}</td><td>${esc(a.action)}</td><td>${esc(a.request_id||'—')}</td><td><pre class="audit-data">${esc(JSON.stringify(a.before_values,null,2)||'—')}</pre></td><td><pre class="audit-data">${esc(JSON.stringify(a.after_values,null,2)||'—')}</pre></td></tr>`).join('')}</tbody></table></div>${pager(d.hasNext)}</section>`;bindPager(render);}
async function download(path,filename){const response=await fetch('/api'+path,{credentials:'same-origin'});if(!response.ok){const e=await response.json();throw new Error(e.error);}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportView(){ $('#content').innerHTML=`<section class="panel"><h2>Выгрузка в Excel</h2><p class="muted">Все 23 поля. Максимальный период регистрации — 45 дней включительно.</p><div class="toolbar"><label>С <input type="date" id="exportFrom" required></label><label>По <input type="date" id="exportTo" required></label>${user.role===0?'<label><input type="checkbox" id="includeArchive"> Включить архив</label>':''}<button class="primary" id="exportButton">Выгрузить .xlsx</button></div></section>`;$('#exportButton').onclick=run(()=>busy($('#exportButton'),async()=>{const from=$('#exportFrom').value,to=$('#exportTo').value;if(!from||!to)throw new Error('Укажите интервал дат регистрации');await download('/export?'+new URLSearchParams({from,to,includeArchive:$('#includeArchive')?.checked?'1':'0'}),`Заявки_с_${fmt(from)}_по_${fmt(to)}.xlsx`);}));}
setInterval(async()=>{if(!user||user.mustChange||document.hidden)return;try{const d=await api('/notifications');notificationCount=d.unread;if($('#notificationCount'))$('#notificationCount').textContent=d.unread;if($('#overlay').innerHTML)return;if(['requests','archive'].includes(view))await loadTable();else if(['dashboard','notifications'].includes(view))await render();}catch(e){if(e.status!==401)console.warn('Обновление временно недоступно');}},30000);
(async()=>{try{const d=await api('/me');user=d.user;csrf=d.csrf;await start();}catch(e){if(e.status===401)login();else $('#app').innerHTML=`<main><h1>Система временно недоступна</h1><div class="error">${esc(e.message)}</div></main>`;}})();
